import { Injectable, Injector } from '@angular/core';
import { HttpEvent, HttpHandler, HttpInterceptor, HttpRequest } from '@angular/common/http';
import { Observable, throwError, TimeoutError } from 'rxjs';
import { catchError, timeout } from 'rxjs/operators';
import { Router } from '@angular/router';
import { SecureStorageService } from '../services/storage/secure-storage.service';
import { AuthValidationService } from '../services/auth-validation/auth-validation.service';

/** Default HTTP request timeout in milliseconds.
 *
 *  Without this, a request whose underlying TCP connection has gone
 *  stale (load balancer dropped a keep-alive, server is unresponsive,
 *  network changed mid-flight) hangs at the OS default — typically
 *  60-120s — and the UI appears frozen the whole time. 30s gives slow
 *  backends room to breathe while keeping the "click does nothing"
 *  symptom under five seconds for the common case (immediate fail) and
 *  capped at 30s for the worst case.
 *
 *  Long-running endpoints (file upload, PDF/DOCX export, transcript
 *  publish, OCR, pagination jobs) are excluded via LONG_RUNNING_PATHS
 *  below — those legitimately take minutes. */
const DEFAULT_TIMEOUT_MS = 30_000;

/** URL substrings whose requests bypass the 30s timeout. These are
 *  endpoints that legitimately run longer than 30s end-to-end:
 *
 *    /upload, /uploadapi  — file uploads of any size; large transcripts
 *                           can be hundreds of MB.
 *    /export              — PDF / DOCX / Excel generation; can take
 *                           minutes for big bundles.
 *    /transcript/publish  — annotation transfer (Python script) is
 *                           bound by transcript size; minutes for full
 *                           hearings.
 *    /transcript/html-file-to-doc-stream — Puppeteer HTML→DOC pipeline.
 *    /batchfile, /hyperlink, /pagination, /ocr, /download — async jobs
 *                           with their own progress reporting.
 *
 *  FormData payloads are also exempted regardless of URL — those are
 *  always file uploads in this codebase, and the upload progress is
 *  surfaced to the user via separate UI so they don't perceive a "frozen"
 *  state. */
const LONG_RUNNING_PATHS: ReadonlyArray<string> = [
  '/upload',
  '/uploadapi',
  '/export',
  '/transcript/publish',
  '/transcript/html-file-to-doc-stream',
  '/batchfile',
  '/hyperlink',
  '/pagination',
  '/ocr',
  '/download',
];

@Injectable()
export class AuthInterceptor implements HttpInterceptor {

  private authValidation: AuthValidationService | null = null;

  constructor(
    private router: Router,
    private storageService: SecureStorageService,
    private injector: Injector
  ) {}

  private getAuthValidation(): AuthValidationService {
    if (!this.authValidation) {
      this.authValidation = this.injector.get(AuthValidationService);
    }
    return this.authValidation;
  }

  intercept(request: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
    const isAuthRequest = request.url.includes('/auth/signin') || request.url.includes('/auth/forgotpassword');
    const token = this.storageService.getStorage('token');

    // Skip Authorization header for login/auth requests to avoid stale token rejection
    if (token && !isAuthRequest) {
      request = request.clone({
        setHeaders: {
          Authorization: `Bearer ${token}`
        }
      });
    }

    const isValidateRequest = request.url.includes('/auth/validate');

    // Decide whether to apply the 30s timeout. Two exemption gates:
    //   1. URL match: any of the LONG_RUNNING_PATHS substrings.
    //   2. Body is FormData: file upload (multipart/form-data) regardless
    //      of URL — the upload-progress UI is the right feedback for these,
    //      not a hard timeout.
    // Composed once per request (cheap) so the pipe stays simple.
    const isFormData = typeof FormData !== 'undefined' && request.body instanceof FormData;
    const isLongRunning = LONG_RUNNING_PATHS.some(p => request.url.includes(p));
    const shouldTimeout = !isFormData && !isLongRunning;

    const stream$ = next.handle(request);
    const guarded$ = shouldTimeout ? stream$.pipe(timeout(DEFAULT_TIMEOUT_MS)) : stream$;

    return guarded$.pipe(
      catchError((error) => {
          // Hung-request detection. RxJS' timeout() emits TimeoutError
          // when no response arrives in DEFAULT_TIMEOUT_MS — that's our
          // signal that the underlying connection is stale (LB dropped
          // it, server is unresponsive, network changed). Surface a
          // recognisable error code so calling code can show a "request
          // timed out, please retry" toast instead of treating it as a
          // generic server error. The UI is no longer frozen — the
          // observable rejects in a bounded time.
          if (error instanceof TimeoutError) {
            console.warn(`AuthInterceptor: request timed out after ${DEFAULT_TIMEOUT_MS}ms — ${request.method} ${request.url}`);
            return throwError(() => ({
              status: 0,
              statusText: 'Request Timeout',
              url: request.url,
              error: { code: 'REQUEST_TIMEOUT', message: `Request timed out after ${DEFAULT_TIMEOUT_MS / 1000}s` },
            }));
          }
          if (error.status === 401) {
            // this.getAuthValidation().clearCache();
            const isSignoutRequest = request.url.includes('/auth/signout');
            if (!isValidateRequest && !isSignoutRequest) {
              this.storageService.logOut();
              this.router.navigate(['/auth/login']).then(success => {
                if (!success) {
                   window.location.href = '/auth/login';
                }
              });
            }
          } else if (error.status === 403) {
            const isRealtimeRoute = this.router.url.includes('/realtime') || this.router.url.includes('/rt-realtime') || this.router.url.includes('/viewer');
            if (!isRealtimeRoute) {
              this.router.navigate(['/user/dashboard']);
            }
          }
        return throwError(error);
      })
    );
  }
}
